WITH x14 AS (SELECT x9.v186900 FROM x22), x15 AS (SELECT MAX(x9.v186899) AS x23, x7.v186661 FROM x25 GROUP BY x9.v186900) SELECT x9.v186898, x7.v186662, STDDEV_SAMP(x9.v186900) OVER (ORDER BY AVG(x7.v186662) ROWS BETWEEN CURRENT ROW AND CURRENT ROW) AS x4, x9.v186898 FROM v186906 AS x7 JOIN v186897 AS x9 ON MBRINTERSECTS(x7.v186661, x7.v186662) WHERE x9.v186898 = '11' AND x7.v186662 = 'd' ORDER BY 10.100000 DESC